/* =============================================================
   The actual CF21 motor mount STL, 2,114 triangles.
   Drag to orbit, scroll to zoom. It turns on its own when idle.
   ============================================================= */
(function(){
'use strict';
var $ = function(s){ return document.querySelector(s); };
var clamp = function(v,a,b){ return v<a?a:(v>b?b:v); };
var RM = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

var MESH_LO=-0.79675518, MESH_HI=1.00000000, MESH_B64="";

function stlViewer(){
  var cv=$('#stlv'); if(!cv||typeof MESH_B64==='undefined') return;
  var ctx=cv.getContext('2d'); if(!ctx) return;
  var W=880,H=880, dpr=Math.min(window.devicePixelRatio||1,2);
  cv.width=W*dpr; cv.height=H*dpr; ctx.setTransform(dpr,0,0,dpr,0,0);

  var bin=atob(MESH_B64), L=bin.length, buf=new ArrayBuffer(L), u8=new Uint8Array(buf), i;
  for(i=0;i<L;i++) u8[i]=bin.charCodeAt(i);
  var q=new Uint16Array(buf), N=q.length/9, sc=(MESH_HI-MESH_LO)/65535;
  var V=new Float32Array(q.length);
  for(i=0;i<q.length;i++) V[i]=q[i]*sc+MESH_LO;
  for(i=0;i<q.length;i+=3){ var yy=V[i+1]; V[i+1]=V[i+2]; V[i+2]=-yy; }

  var NM=new Float32Array(N*3), CT=new Float32Array(N*3);
  for(var t=0;t<N;t++){
    var o=t*9;
    var ax=V[o],ay=V[o+1],az=V[o+2],bx=V[o+3],by=V[o+4],bz=V[o+5],cx=V[o+6],cy=V[o+7],cz=V[o+8];
    var ux=bx-ax,uy=by-ay,uz=bz-az,vx=cx-ax,vy=cy-ay,vz=cz-az;
    var nx=uy*vz-uz*vy, ny=uz*vx-ux*vz, nz=ux*vy-uy*vx;
    var ln=Math.sqrt(nx*nx+ny*ny+nz*nz)||1;
    NM[t*3]=nx/ln; NM[t*3+1]=ny/ln; NM[t*3+2]=nz/ln;
    CT[t*3]=(ax+bx+cx)/3; CT[t*3+1]=(ay+by+cy)/3; CT[t*3+2]=(az+bz+cz)/3;
  }

  var yaw=-0.6, pit=0.28, vyaw=0, vpit=0, zoom=1, drag=false, lx=0, ly=0, touched=false;
  var hint=$('#stlhint'), vis=true, order=[];
  if('IntersectionObserver' in window)
    new IntersectionObserver(function(e){ vis=e[0].isIntersecting; },{threshold:0.02}).observe(cv);

  function orbit(dx,dy){
    vyaw=dx*0.0085; vpit=dy*0.0085;
    yaw+=vyaw; pit=clamp(pit+vpit,-1.35,1.35);
  }
  function stop(){
    drag=false; cv.classList.remove('drag');
    document.removeEventListener('mousemove', onMove);
    document.removeEventListener('mouseup', stop);
    document.removeEventListener('touchmove', onTouch);
    document.removeEventListener('touchend', stop);
    document.removeEventListener('touchcancel', stop);
    window.removeEventListener('blur', stop);
  }
  function onMove(e){
    if(!drag) return;
    orbit(e.clientX-lx, e.clientY-ly); lx=e.clientX; ly=e.clientY;
  }
  function onTouch(e){
    if(!drag || !e.touches || !e.touches[0]) return;
    var t0=e.touches[0];
    orbit(t0.clientX-lx, t0.clientY-ly); lx=t0.clientX; ly=t0.clientY;
  }
  cv.addEventListener('mousedown',function(e){
    if(e.button!==0) return;
    drag=true; lx=e.clientX; ly=e.clientY; cv.classList.add('drag');
    if(!touched){ touched=true; if(hint) hint.classList.add('gone'); }
    e.preventDefault();
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', stop);
    window.addEventListener('blur', stop);
  });
  cv.addEventListener('touchstart',function(e){
    if(!e.touches || !e.touches[0]) return;
    drag=true; lx=e.touches[0].clientX; ly=e.touches[0].clientY; cv.classList.add('drag');
    if(!touched){ touched=true; if(hint) hint.classList.add('gone'); }
    document.addEventListener('touchmove', onTouch, {passive:true});
    document.addEventListener('touchend', stop);
    document.addEventListener('touchcancel', stop);
  },{passive:true});
  cv.addEventListener('dragstart',function(e){ e.preventDefault(); });
  cv.addEventListener('wheel',function(e){
    zoom=clamp(zoom*(1-e.deltaY*0.0011),0.55,2.6);
    if(!touched){ touched=true; if(hint) hint.classList.add('gone'); }
    e.preventDefault();
  },{passive:false});

  function frame(){
    requestAnimationFrame(frame);
    if(!vis) return;
    if(!drag){
      yaw+=vyaw; pit=clamp(pit+vpit,-1.35,1.35);
      vyaw*=0.94; vpit*=0.94;
      if(Math.abs(vyaw)<0.0006) vyaw=0;
      if(Math.abs(vpit)<0.0006) vpit=0;
      if(!vyaw && !RM) yaw+=0.0032;
    }
    var cyw=Math.cos(yaw), syw=Math.sin(yaw), cpt=Math.cos(pit), spt=Math.sin(pit);
    var S=Math.min(W,H)*0.40*zoom, ox=W/2, oy=H/2;
    ctx.clearRect(0,0,W,H);
    var lgt=[-0.34,0.66,0.67];
    order.length=0;
    for(var k=0;k<N;k++){
      var k3=k*3;
      var nx0=NM[k3], ny0=NM[k3+1], nz0=NM[k3+2];
      var nx1=nx0*cyw+nz0*syw, nz1=-nx0*syw+nz0*cyw;
      var ny2=ny0*cpt-nz1*spt, nz2=ny0*spt+nz1*cpt;
      if(nz2<=0.001) continue;
      var cx0=CT[k3], cy0=CT[k3+1], cz0=CT[k3+2];
      var cz1=-cx0*syw+cz0*cyw;
      order.push([k, cy0*spt+cz1*cpt, nx1*lgt[0]+ny2*lgt[1]+nz2*lgt[2], nz2]);
    }
    order.sort(function(a,b){ return a[1]-b[1]; });
    for(var j=0;j<order.length;j++){
      var f=order[j], o2=f[0]*9;
      var lam=Math.max(0,f[2]), rim=Math.pow(1-Math.min(1,f[3]),2.4);
      var sh=0.20+0.80*Math.pow(lam,0.7);
      var r=Math.round((0.10+(0.95-0.10)*sh+0.29*rim*0.55)*255);
      var g=Math.round((0.09+(0.91-0.09)*sh+0.20*rim*0.55)*255);
      var b2=Math.round((0.13+(0.80-0.13)*sh+0.44*rim*0.55)*255);
      ctx.fillStyle='rgb('+Math.min(255,r)+','+Math.min(255,g)+','+Math.min(255,b2)+')';
      ctx.beginPath();
      for(var v=0;v<3;v++){
        var vo=o2+v*3, X=V[vo], Y=V[vo+1], Z=V[vo+2];
        var X1=X*cyw+Z*syw, Z1=-X*syw+Z*cyw;
        var Y2=Y*cpt-Z1*spt;
        var sx=ox+X1*S, sy=oy-Y2*S;
        if(v===0) ctx.moveTo(sx,sy); else ctx.lineTo(sx,sy);
      }
      ctx.closePath(); ctx.fill();
    }
  }
  requestAnimationFrame(frame);
}

if(document.readyState === 'loading')
  document.addEventListener('DOMContentLoaded', stlViewer);
else stlViewer();
})();
